-- Demo company fake data — Beverage Stock
-- Generated for demo/sales purposes. Run in the Supabase SQL editor.
-- Covers Jun-Aug 2026 across all 3 locations (ZC/EC/SC), with a couple of
-- items deliberately run low (Klipdrift Brandy, Sauvignon Blanc) to show
-- the reorder-alert UI.


























-- Verification:
select 'bev_items' as t, count(*) from bev_items where company_id = (select id from companies where slug='demo')
union all select 'bev_purchases', count(*) from bev_purchases where company_id = (select id from companies where slug='demo')
union all select 'bev_issues', count(*) from bev_issues where company_id = (select id from companies where slug='demo');
